{
  "architecture": {
    "services": [
      {
        "name": "calc",
        "path": "services/calc",
        "language": "go",
        "public_interface": {
          "kind": "ui",
          "elements": [
            {
              "page": "Calc",
              "role": "button",
              "name": "Halve"
            },
            {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            },
            {
              "page": "Calc",
              "role": "textbox",
              "name": "Idempotency key"
            }
          ]
        }
      }
    ],
    "concepts": [
      {
        "concept": "number ready",
        "block": "given",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          }
        ],
        "does": "Enter the given number into the Number field."
      },
      {
        "concept": "number result",
        "block": "then",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          }
        ],
        "does": "Compare the displayed Number text with the expected result."
      },
      {
        "concept": "halve",
        "block": "when",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "button",
              "name": "Halve"
            }
          },
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Idempotency key"
            }
          }
        ],
        "does": "Set Idempotency key to a fresh label for the requested halving and press Halve once. For a repeated request, reuse the label and press Halve again; Number must stay unchanged."
      }
    ],
    "terms": [
      {
        "term": "idempotency key",
        "technical": "The text typed into the Calc page's \"Idempotency key\" textbox, which the calculator remembers alongside the last applied halving so a second request carrying the same text is ignored",
        "observed_by": "The When step fills the \"Idempotency key\" textbox with the label named in the step before pressing Halve, and reuses that same label for a repeated press; the Then step never reads the key itself — it observes its effect by comparing the displayed Number with the expected value, unchanged after the repeat"
      }
    ]
  }
}

{
  "roles": [
    {
      "name": "Product Owner",
      "description": "Owns meanings."
    }
  ],
  "concepts": {
    "given": [
      {
        "concept": "number ready",
        "means": "A number is entered before the action.",
        "terms": []
      }
    ],
    "when": [
      {
        "concept": "halve",
        "means": "Halve the entered number once with the supplied idempotency key.",
        "terms": ["idempotency key"]
      }
    ],
    "then": [
      {
        "concept": "number result",
        "means": "Compare the displayed number with an expected value.",
        "terms": ["idempotency key"]
      },
      {
        "concept": "unused",
        "means": "The settlement ledger has a reconciled nostro balance.",
        "terms": []
      }
    ]
  },
  "glossary": [
    {
      "term": "idempotency key",
      "means": "The label a caller supplies with a request so that repeating the request with the same label changes the number only once."
    }
  ],
  "description": "A calculator accepts a number and a request label. Repeating a request with the same label changes the number only once.",
  "language_policy": "The request label is presented to users as an idempotency key. Keep this exact domain name in the product meanings and declare it when needed."
}
